from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    if h <= 0 or w <= 0 or n < 0 or n > len(tiles):
        return False

    full = (1 << (h * w)) - 1
    dims = [set(((a, b), (b, a))) for a, b in tiles[:n]]
    areas = [a * b for a, b in tiles[:n]]

    @lru_cache(None)
    def area_can_fill(used: int, remaining: int) -> bool:
        possible = {0}
        for i, area in enumerate(areas):
            if not (used >> i) & 1:
                possible |= {x + area for x in tuple(possible) if x + area <= remaining}
        return remaining in possible

    @lru_cache(None)
    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True
        remaining = h * w - occupied.bit_count()
        if not area_can_fill(used, remaining):
            return False

        # A valid tiling must cover the first unoccupied cell, which removes
        # redundant placement orders from the search.
        empty = (~occupied) & full
        cell = (empty & -empty).bit_length() - 1
        row, col = divmod(cell, w)

        for i in range(n):
            if (used >> i) & 1:
                continue
            for th, tw in dims[i]:
                if th > h or tw > w:
                    continue
                top_min, top_max = max(0, row - th + 1), min(row, h - th)
                left_min, left_max = max(0, col - tw + 1), min(col, w - tw)
                for top in range(top_min, top_max + 1):
                    for left in range(left_min, left_max + 1):
                        row_bits = ((1 << tw) - 1) << (top * w + left)
                        placement = 0
                        for rr in range(th):
                            placement |= row_bits << (rr * w)
                        if not (placement & occupied) and search(
                            occupied | placement, used | (1 << i)
                        ):
                            return True
        return False

    return search(0, 0)

