MOD = 998244353


def count_polish_sequences(n: int, a: list[int]) -> int:
    """Count Polish sequences of length n lexicographically at most a.

    Polish sequences are preorder child-count encodings of ordered rooted
    trees. The number of unfilled child positions starts at one, stays positive
    before the last item, and becomes zero at the last item.
    """
    fact = [1] * (2 * n + 1)
    for i in range(1, 2 * n + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (2 * n + 1)
    invfact[2 * n] = pow(fact[2 * n], MOD - 2, MOD)
    for i in range(2 * n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    def choose(top: int, bottom: int) -> int:
        if bottom < 0 or bottom > top or top < 0:
            return 0
        return fact[top] * invfact[bottom] % MOD * invfact[top - bottom] % MOD

    def forests(nodes: int, roots: int) -> int:
        # Ordered forests with roots roots and nodes total nodes.
        if nodes == 0:
            return int(roots == 0)
        if roots < 1 or roots > nodes:
            return 0
        return roots * fact[nodes - 1] % MOD * invfact[nodes] % MOD * choose(
            2 * nodes - roots - 1, nodes - roots
        ) % MOD

    answer = 0
    slots = 1
    for i, bound in enumerate(a):
        remaining = n - i - 1

        # For a smaller value x, the suffix is a forest with slots - 1 + x
        # roots. Sum the ballot counts for all such x.
        if remaining:
            low = max(1, slots - 1)
            high = min(remaining, slots + bound - 2)
            for roots in range(low, high + 1):
                answer += forests(remaining, roots)
        elif slots == 1 and bound > 0:
            # A smaller final value can close the last open position only when
            # it is zero.
            answer += 1

        slots += bound - 1
        if slots < 0:
            break
        if slots == 0:
            if i == n - 1:
                answer += 1
            break

    return answer % MOD

