def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """ Given a grid with H rows and W columns consisting of '1', '2', '3', and '?',
    count how many ways we can replace each '?' with '1', '2', or '3' such that
    any two adjacent (edge-sharing) cells contain different digits.

    Return the count modulo 998244353.

    Args:
        H: Number of rows (1 <= H, H * W <= 200)
        W: Number of columns (1 <= W, H * W <= 200)
        grid: List of strings representing the grid, where grid[i] is the i-th row

    Returns:
        The number of valid grid configurations modulo 998244353

    >>> count_valid_grids(2, 2, ['1?', '??'])
    6
    >>> count_valid_grids(2, 3, ['123', '3?1'])
    0
    >>> count_valid_grids(1, 1, ['?'])
    3
    """
    mod = 998244353

    # Sweep along the longer dimension so that the row state has the
    # smaller dimension (at most 14 under the input size bound).
    if W > H:
        rows = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        width = H
    else:
        rows = grid
        width = W

    domains = []
    for row in rows:
        domains.append([
            (0, 1, 2) if ch == "?" else (ord(ch) - ord("1"),)
            for ch in row
        ])

    def patterns(allowed, previous=None):
        current = [0] * width

        def build(pos):
            if pos == width:
                yield tuple(current)
                return
            left = current[pos - 1] if pos else -1
            for color in allowed[pos]:
                if color == left:
                    continue
                if previous is not None and color == previous[pos]:
                    continue
                current[pos] = color
                yield from build(pos + 1)

        yield from build(0)

    dp = {state: 1 for state in patterns(domains[0])}
    for allowed in domains[1:]:
        next_dp = {}
        for previous, ways in dp.items():
            for state in patterns(allowed, previous):
                next_dp[state] = next_dp.get(state, 0) + ways
        dp = {state: ways % mod for state, ways in next_dp.items()}
        if not dp:
            return 0

    return sum(dp.values()) % mod

