def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to the rules in the problem statement. Coordinates
    identify unit squares by their centers, so floor division works for negative
    coordinates as well.
    """
    def tile(x, y):
        i, j = x // K, y // K
        if (i + j) % 2 == 0:
            return (0, i, j, y - j * K)
        return (1, i, j, x - i * K)

    start = tile(S_x, S_y)
    goal = tile(T_x, T_y)
    if start == goal:
        return 0

    # For nearby tiles, search the actual adjacency graph. The graph's branching
    # factor is at most K, and its relevant radius is small.
    di = abs(start[1] - goal[1])
    dj = abs(start[2] - goal[2])
    if max(di, dj) <= 30 and K <= 500:
        from collections import deque

        q = deque([(start, 0)])
        seen = {start}
        while q:
            (o, i, j, k), d = q.popleft()
            if o == 0:  # horizontal tile
                ns = []
                if k:
                    ns.append((0, i, j, k - 1))
                if k + 1 < K:
                    ns.append((0, i, j, k + 1))
                # Its short edges meet the end tile in the adjacent x block.
                ns.append((1, i - 1, j, K - 1))
                ns.append((1, i + 1, j, 0))
                # Its long edges meet all tiles in the neighboring y block.
                if k == 0:
                    ns.extend((1, i, j - 1, a) for a in range(K))
                if k == K - 1:
                    ns.extend((1, i, j + 1, a) for a in range(K))
            else:  # vertical tile
                ns = []
                if k:
                    ns.append((1, i, j, k - 1))
                if k + 1 < K:
                    ns.append((1, i, j, k + 1))
                # Its short edges meet the end tile in the adjacent y block.
                ns.append((0, i, j - 1, K - 1))
                ns.append((0, i, j + 1, 0))
                # Its long edges meet all tiles in the neighboring x block.
                if k == 0:
                    ns.extend((0, i - 1, j, a) for a in range(K))
                if k == K - 1:
                    ns.extend((0, i + 1, j, a) for a in range(K))
            nd = d + 1
            for nxt in ns:
                if nxt == goal:
                    return nd
                if nxt not in seen:
                    seen.add(nxt)
                    q.append((nxt, nd))

    # At large distances each move can advance by one block diagonally. This
    # gives the Chebyshev block distance, with two tile transitions per step.
    return 2 * max(abs(start[1] - goal[1]), abs(start[2] - goal[2]))

