from functools import lru_cache


@lru_cache(maxsize=None)
def _digit_products(modulus: int, max_len: int):
    """Return counts of digit strings by length, digit sum, and product mod modulus."""
    table = [[[0] * modulus for _ in range(9 * length + 1)]
             for length in range(max_len + 1)]
    table[0][0][1 % modulus] = 1

    for length in range(1, max_len + 1):
        previous = table[length - 1]
        current = table[length]
        for digit_sum, remainders in enumerate(previous):
            for remainder, count in enumerate(remainders):
                if not count:
                    continue
                for digit in range(10):
                    new_sum = digit_sum + digit
                    if new_sum <= 9 * length:
                        current[new_sum][(remainder * digit) % modulus] += count
    return table


def _count_up_to(n: int) -> int:
    if n <= 0:
        return 0

    digits = list(map(int, str(n)))
    length = len(digits)
    answer = 0

    # Count all shorter positive numbers, grouped by their digit length.
    for number_length in range(1, length):
        for digit_sum in range(1, 9 * number_length + 1):
            ways = _digit_products(digit_sum, number_length - 1)
            for first in range(1, 10):
                remaining_sum = digit_sum - first
                if remaining_sum < 0 or remaining_sum > 9 * (number_length - 1):
                    continue
                suffix = ways[number_length - 1][remaining_sum]
                answer += sum(suffix[r] for r in range(digit_sum)
                              if (first * r) % digit_sum == 0)

    # Count length-digit numbers up to n by fixing each prefix in turn.
    for digit_sum in range(1, 9 * length + 1):
        ways = _digit_products(digit_sum, length - 1)
        prefix_sum = 0
        prefix_product = 1
        for position, bound_digit in enumerate(digits):
            remaining_len = length - position - 1
            low = 1 if position == 0 else 0
            for digit in range(low, bound_digit):
                remaining_sum = digit_sum - prefix_sum - digit
                if remaining_sum < 0 or remaining_sum > 9 * remaining_len:
                    continue
                factor = (prefix_product * digit) % digit_sum
                suffix = ways[remaining_len][remaining_sum]
                answer += sum(suffix[r] for r in range(digit_sum)
                              if (factor * r) % digit_sum == 0)
            if position == 0 and bound_digit == 0:
                break
            prefix_sum += bound_digit
            prefix_product = (prefix_product * bound_digit) % digit_sum
        else:
            if prefix_sum == digit_sum and prefix_product == 0:
                answer += 1
    return answer


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)

