def count_in_degree_sequences(n: int, s: str) -> int:
    """Count distinct indegree sequences of orientations of the specified graph."""
    # A cycle edge i -- i+1 is encoded by b_i=1 when it points into i.
    # The cycle contribution at i is 1 + b_i - b_(i-1). An optional spoke
    # adds either zero or one to that contribution.
    #
    # For a proposed sequence of indegrees, its possible edge-bit sequences
    # form a two-state automaton. Determinizing from each possible starting
    # bit lets us count output sequences (rather than orientations), with
    # cyclic closure checked at the end.
    def advance(mask: int, y: int, spoke: bool) -> int:
        nxt = 0
        for prev in (0, 1):
            if mask & (1 << prev):
                for cur in (0, 1):
                    base = 1 + cur - prev
                    if y == base or (spoke and y == base + 1):
                        nxt |= 1 << cur
        return nxt

    transitions = [
        [[advance(mask, y, bool(spoke)) for y in range(4)] for mask in range(4)]
        for spoke in range(2)
    ]

    # Pair of reachable-state masks, one for each fixed initial edge bit.
    dp = {(1, 2): 1}
    for ch in s:
        ndp = {}
        trans = transitions[ch == "1"]
        for (from_zero, from_one), ways in dp.items():
            for y in range(4):
                a = trans[from_zero][y]
                b = trans[from_one][y]
                if a or b:
                    key = (a, b)
                    ndp[key] = (ndp.get(key, 0) + ways) % MOD
        dp = ndp
    answer = 0
    for (from_zero, from_one), ways in dp.items():
        if (from_zero & 1) or (from_one & 2):
            answer = (answer + ways) % MOD
    return answer

