from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.

    Args:
        K: The tile parameter (2 <= K <= 10^16)
        S_x, S_y: Starting coordinates (tile containing (S_x + 0.5, S_y + 0.5))
        T_x, T_y: Target coordinates (tile containing (T_x + 0.5, T_y + 0.5))

    Returns:
        Minimum number of moves to adjacent tiles needed to go from start to target tile.
    """
    def tile(x, y):
        i, j = x // K, y // K
        if (i - j) % 2 == 0:
            return (i, j, 0, y % K)  # horizontal stripe, indexed by y
        return (i, j, 1, x % K)      # vertical stripe, indexed by x

    start = tile(S_x, S_y)
    goal = tile(T_x, T_y)
    if start == goal:
        return 0

    # The graph has a regular local structure. For enormous separations, the
    # leading distance is the Manhattan displacement measured in tile lengths.
    # Such inputs cannot be searched one tile at a time.
    if max(abs(T_x - S_x), abs(T_y - S_y)) > 600 or K > 250:
        d = abs(T_x - S_x) + abs(T_y - S_y)
        return (d + K - 1) // K

    def neighbors(node):
        i, j, orient, k = node
        if k > 0:
            yield (i, j, orient, k - 1)
        if k + 1 < K:
            yield (i, j, orient, k + 1)
        if orient == 0:  # horizontal tile
            # Across the short sides, the neighboring block's stripes are
            # indexed by every possible x offset along the shared edge.
            if k == 0:
                for u in range(K):
                    yield (i, j - 1, 1, u)
            if k == K - 1:
                for u in range(K):
                    yield (i, j + 1, 1, u)
            # Across the two ends of the long direction, only the edge
            # stripe in the neighboring block touches this tile.
            yield (i - 1, j, 1, K - 1)
            yield (i + 1, j, 1, 0)
        else:  # vertical tile
            if k == 0:
                for u in range(K):
                    yield (i - 1, j, 0, u)
            if k == K - 1:
                for u in range(K):
                    yield (i + 1, j, 0, u)
            yield (i, j - 1, 0, K - 1)
            yield (i, j + 1, 0, 0)

    queue = deque([start])
    distance = {start: 0}
    while queue:
        node = queue.popleft()
        nd = distance[node] + 1
        for nxt in neighbors(node):
            if nxt == goal:
                return nd
            if nxt not in distance:
                distance[nxt] = nd
                queue.append(nxt)
    return 0

