from typing import List


MOD = 998244353


def count_valid_strings(K: int, C: List[int]) -> int:
    """Count uppercase strings of lengths 1 through K with per-letter occurrence caps."""
    inv_fact = [1] * (K + 1)
    for i in range(1, K + 1):
        inv_fact[i] = inv_fact[i - 1] * pow(i, MOD - 2, MOD) % MOD

    # Product of EGF polynomials for letters whose caps are below K.
    coeff = [0] * (K + 1)
    coeff[0] = 1
    unrestricted = 0
    for cap in C:
        if cap >= K:
            unrestricted += 1
            continue
        updated = [0] * (K + 1)
        for old_len, value in enumerate(coeff):
            if value == 0:
                continue
            for added in range(min(cap, K - old_len) + 1):
                updated[old_len + added] = (
                    updated[old_len + added] + value * inv_fact[added]
                ) % MOD
        coeff = updated

    fact = 1
    result = 0
    if unrestricted:
        # Unrestricted letters contribute exp(unrestricted*x).
        u_powers = [1] * (K + 1)
        for i in range(1, K + 1):
            u_powers[i] = u_powers[i - 1] * unrestricted % MOD
        for length in range(1, K + 1):
            fact = fact * length % MOD
            egf_coefficient = 0
            for old_len in range(length + 1):
                egf_coefficient += (
                    coeff[old_len]
                    * inv_fact[length - old_len]
                    % MOD
                    * u_powers[length - old_len]
                    % MOD
                )
            result = (result + fact * egf_coefficient) % MOD
    else:
        for length in range(1, K + 1):
            fact = fact * length % MOD
            result = (result + fact * coeff[length]) % MOD
    return result

