from typing import List

_MOD = 998244353
_ROOT = 3


def _ntt(a, invert):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(_ROOT, (_MOD - 1) // length, _MOD)
        if invert:
            wlen = pow(wlen, _MOD - 2, _MOD)
        half = length >> 1
        for start in range(0, n, length):
            w = 1
            end = start + half
            for i in range(start, end):
                u = a[i]
                v = a[i + half] * w % _MOD
                a[i] = (u + v) % _MOD
                a[i + half] = (u - v) % _MOD
                w = w * wlen % _MOD
        length <<= 1

    if invert:
        inv_n = pow(n, _MOD - 2, _MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % _MOD


def _multiply(a, b, limit):
    out_len = min(limit, len(a) + len(b) - 1)
    if len(a) * len(b) <= 4096:
        out = [0] * out_len
        for i, x in enumerate(a):
            upto = min(len(b), out_len - i)
            for j in range(upto):
                out[i + j] = (out[i + j] + x * b[j]) % _MOD
        return out

    n = 1
    full_len = len(a) + len(b) - 1
    while n < full_len:
        n <<= 1
    fa = a + [0] * (n - len(a))
    fb = b + [0] * (n - len(b))
    _ntt(fa, False)
    _ntt(fb, False)
    for i in range(n):
        fa[i] = fa[i] * fb[i] % _MOD
    _ntt(fa, True)
    return fa[:out_len]


def count_valid_strings(K: int, C: List[int]) -> int:
    """Count uppercase strings of length 1 through K with each letter count
    bounded by its corresponding entry in C, modulo 998244353.
    """
    fact = [1] * (K + 1)
    for i in range(1, K + 1):
        fact[i] = fact[i - 1] * i % _MOD
    invfact = [1] * (K + 1)
    invfact[K] = pow(fact[K], _MOD - 2, _MOD)
    for i in range(K, 0, -1):
        invfact[i - 1] = invfact[i] * i % _MOD

    polys = []
    for cap in C:
        degree = min(cap, K)
        polys.append(invfact[:degree + 1])

    while len(polys) > 1:
        next_level = []
        for i in range(0, len(polys), 2):
            if i + 1 == len(polys):
                next_level.append(polys[i])
            else:
                next_level.append(_multiply(polys[i], polys[i + 1], K + 1))
        polys = next_level

    coeff = polys[0]
    return sum(coeff[n] * fact[n] for n in range(1, len(coeff))) % _MOD
